/**
 * Shared helpers for the generators (`concepts.ts`, `paths.ts`,
 * `addresses.ts`).
 *
 * Output rules (all three generators):
 * - Output is deterministic: files are produced in sorted order, every
 *   generated file starts with a `GENERATED by …` MDX comment, and nothing
 *   depends on the clock or the environment.
 * - Generated folders (`snippets/concepts/**`, `snippets/paths/**`) are owned
 *   by the generator: a generated file that is no longer produced is deleted.
 *   A file in those folders WITHOUT the generated header is never deleted; it
 *   is reported as a problem instead.
 * - `--check` computes everything in memory and reports what would change
 *   (missing, stale and orphaned files, plus `--sync` edits), without writing.
 * - `--sync` edits content pages through the source-preserving `mdxCodec`, and
 *   only touches elements that carry the generator's `data-*` marker.
 *
 * Output patterns were chosen from an SSR probe: raw
 * `<nav>`, `<details>`, `<noscript>` and `<abbr>` were dropped, and
 * Tooltip `tip`/`headline`/`cta`/`href` only reached the client payload. So:
 * `role="navigation"` on a `<div>`, `<Accordion>`/visible fences instead of
 * `<details>`, and a `nojs-only` sibling span next to every Tooltip.
 */
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { mdxCodec, treeFingerprint } from "../lib/codec.ts";
import { langOfFile, listPageFiles, pageToFile } from "../lib/content-paths.ts";
import { docsRoot as defaultDocsRoot, toPosix } from "../lib/paths.ts";
import { DEFAULT_LOCALE, DOCS_LOCALES } from "../lib/locales.ts";
import type { AstNode } from "../types.ts";

export const GENERATED_MARK =
  "GENERATED by packages/docs-tooling/src/generators/";

/** Common options for every generator. */
export interface GeneratorOptions {
  /** Docs content root (defaults to apps/docs/content). Tests point this at a temp dir. */
  docsRoot?: string;
  /** Compute in memory and report; never write. */
  check?: boolean;
  /** Also rewrite marked elements in content pages. */
  sync?: boolean;
  log?: (msg: string) => void;
}

export interface Problem {
  level: "error" | "warn";
  file?: string;
  message: string;
}

export interface GeneratorResult {
  /** Files written (or, with `check`, that would be written). Docs-root relative. */
  written: string[];
  /** Generated files removed (or that would be removed). */
  removed: string[];
  /** Content pages rewritten by `--sync` (or that would be). */
  synced: string[];
  problems: Problem[];
  /** `false` when `check` found drift or any error was reported. */
  ok: boolean;
}

export function emptyResult(): GeneratorResult {
  return { written: [], removed: [], synced: [], problems: [], ok: true };
}

export function finish(r: GeneratorResult, check: boolean): GeneratorResult {
  const drift = r.written.length + r.removed.length + r.synced.length > 0;
  r.ok = !r.problems.some((p) => p.level === "error") && !(check && drift);
  r.written.sort();
  r.removed.sort();
  r.synced.sort();
  return r;
}

export function resolveDocsRoot(opts: GeneratorOptions) {
  return opts.docsRoot ?? defaultDocsRoot;
}

/** The generated-file header, as an MDX comment (renders nothing). */
export function header(generator: string, sources: string[], script: string) {
  return `{/* ${GENERATED_MARK}${generator} from ${sources.join(", ")}. Do not edit: change the source and run \`pnpm --filter @workspace/docs-tooling ${script}\`. */}\n`;
}

// ---------------------------------------------------------------------------
// Text escaping for generated MDX
// ---------------------------------------------------------------------------

/**
 * A plain-text JSX attribute (`name="..."`). The SSR probe dropped `{…}`
 * expressions in snippet content (`{"text"}` children vanished from the
 * server HTML), so generated snippets never use expressions: attributes are
 * string literals and text is escaped markdown (`mdText`).
 */
export function attr(name: string, s: string) {
  const v = s.replace(/\s*\n\s*/g, " ");
  if (!v.includes('"')) return `${name}="${v}"`;
  if (!v.includes("'")) return `${name}='${v}'`;
  return `${name}="${v.replace(/"/g, "&quot;")}"`;
}

/**
 * A plain-text value as a JSX attribute expression (`name={"..."}`).
 * Attribute expressions render server-side (a `<Card title={"…"}>` in a
 * snippet); prefer `attr` anyway. Kept for other
 * generators that import it.
 */
export function jsAttr(name: string, s: string) {
  return `${name}={${JSON.stringify(s)}}`;
}

/**
 * Author-supplied *inline markdown* (concept `short`/`like`, step summaries).
 * Markdown emphasis, code and links are kept; `{`, `}`, `<` and `>` are
 * escaped so they cannot open JSX or expressions; newlines collapse.
 */
export function mdInline(s: string) {
  return s
    .replace(/\s*\n\s*/g, " ")
    .trim()
    .replace(/[{}<>]/g, (c) => `\\${c}`);
}

/** Markdown-escaped plain text (labels, titles, link text). */
export function mdText(s: string) {
  return s
    .replace(/\s*\n\s*/g, " ")
    .replace(/[\\`*_[\]{}<>#|~]/g, (c) => `\\${c}`);
}

/** Inline markdown -> plain text (Tooltip `tip`, aria labels). */
export function plainText(md: string) {
  return md
    .replace(/\s*\n\s*/g, " ")
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/`([^`]*)`/g, "$1")
    .replace(/(\*\*|__)(.+?)\1/g, "$2")
    .replace(/(\*|_)(.+?)\1/g, "$2")
    .replace(/\\([\\`*_[\]{}<>#|~.!()-])/g, "$1")
    .trim();
}

/** Errors for inline markdown that would not survive as card text. */
export function checkInlineMarkdown(s: string): string | undefined {
  if (/<\/?[a-zA-Z]/.test(s))
    return "contains raw HTML; use markdown (*em*, **strong**, `code`, [link](/x))";
  if (/\n\s*\n/.test(s)) return "contains a blank line (one paragraph only)";
  return undefined;
}

/** A fence that cannot be closed by the content (longest backtick run + 1). */
export function fence(lang: string, body: string) {
  const longest = Math.max(
    2,
    ...[...body.matchAll(/`+/g)].map((m) => m[0].length),
  );
  const ticks = "`".repeat(longest + 1);
  return `${ticks}${lang}\n${body.replace(/\n+$/, "")}\n${ticks}`;
}

// ---------------------------------------------------------------------------
// Locales and pages
// ---------------------------------------------------------------------------

export { langOfFile };

/** `/developers/docs/a/b#x` -> the page file that serves it, or undefined. */
export function pageFileFor(docsRoot: string, href: string) {
  if (!href.startsWith("/")) return undefined;
  const p = href
    .replace(/[#?].*$/, "")
    .replace(/\/+$/, "")
    .replace(/^\//, "");
  for (const page of [p, `${p}/index`]) {
    const file = pageToFile(page);
    const abs = file && path.join(docsRoot, file);
    if (abs && existsSync(abs)) return abs;
  }
  return undefined;
}

/**
 * Localize an English href for `lang`: `/developers/docs/x` ->
 * `/<lang>/developers/docs/x` when the translated page exists, else the
 * English page. Cookbook and external links are returned unchanged.
 */
export function localizeHref(docsRoot: string, href: string, lang: string) {
  if (lang === DEFAULT_LOCALE || !href.startsWith("/")) return href;
  if (href.startsWith("/developers/cookbook")) return href;
  const m = /^([^#?]*)(.*)$/.exec(href)!;
  const localized = `/${lang}${m[1]}`;
  return pageFileFor(docsRoot, localized) ? `${localized}${m[2]}` : href;
}

/** Locales that have a `<dir>/<base>.<loc>.json` source next to the EN one. */
export function sourceLanguages(dir: string, base: string) {
  const langs = [DEFAULT_LOCALE];
  for (const loc of DOCS_LOCALES)
    if (existsSync(path.join(dir, `${base}.${loc}.json`))) langs.push(loc);
  return langs;
}

export function readJson(file: string): unknown {
  return JSON.parse(readFileSync(file, "utf8"));
}

export function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Merge locale UI strings over the English defaults (strings only). */
export function uiStrings<T extends Record<string, string>>(
  defaults: T,
  ...layers: unknown[]
): T {
  const out: Record<string, string> = { ...defaults };
  for (const layer of layers)
    if (isRecord(layer))
      for (const k of Object.keys(defaults))
        if (typeof layer[k] === "string") out[k] = layer[k] as string;
  return out as T;
}

// ---------------------------------------------------------------------------
// Writing generated files
// ---------------------------------------------------------------------------

function walk(dir: string, out: string[] = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir).sort()) {
    const abs = path.join(dir, name);
    if (statSync(abs).isDirectory()) walk(abs, out);
    else out.push(abs);
  }
  return out;
}

/**
 * Write `files` (absolute path -> content) and delete generated files under
 * `ownedDirs` that are no longer produced. With `check`, only report.
 */
export function applyOutputs(
  docsRoot: string,
  files: Map<string, string>,
  ownedDirs: string[],
  check: boolean,
  r: GeneratorResult,
) {
  const rel = (abs: string) => toPosix(path.relative(docsRoot, abs));
  for (const abs of [...files.keys()].sort()) {
    const want = files.get(abs)!;
    const have = existsSync(abs) ? readFileSync(abs, "utf8") : undefined;
    if (have === want) continue;
    r.written.push(rel(abs));
    if (!check) {
      mkdirSync(path.dirname(abs), { recursive: true });
      writeFileSync(abs, want);
    }
  }
  for (const dir of ownedDirs) {
    for (const abs of walk(dir)) {
      if (files.has(abs)) continue;
      const text = readFileSync(abs, "utf8");
      if (!text.includes(GENERATED_MARK)) {
        r.problems.push({
          level: "error",
          file: rel(abs),
          message:
            "hand-written file in a generated folder; move it out (generated folders are overwritten)",
        });
        continue;
      }
      r.removed.push(rel(abs));
      if (!check) rmSync(abs);
    }
  }
}

// ---------------------------------------------------------------------------
// Content pages and --sync
// ---------------------------------------------------------------------------

/** Every page file (absolute path, all languages) under the content root. */
export function listContentPages(docsRoot: string): string[] {
  return listPageFiles(docsRoot).map((f) => path.join(docsRoot, f));
}

export interface SyncFile {
  /** docs-root relative, posix. */
  rel: string;
  lang: string;
}

/**
 * Run `edit` over every content page whose text passes `precheck`, through
 * the source-preserving codec. `edit` mutates the tree and returns true when
 * it changed something. Changed files are written unless `check`.
 */
export function syncPages(
  docsRoot: string,
  precheck: (source: string) => boolean,
  edit: (tree: AstNode, file: SyncFile, problems: Problem[]) => boolean,
  check: boolean,
  r: GeneratorResult,
) {
  for (const abs of listContentPages(docsRoot)) {
    const source = readFileSync(abs, "utf8");
    if (!precheck(source)) continue;
    const rel = toPosix(path.relative(docsRoot, abs));
    const file = { rel, lang: langOfFile(rel) };
    let parsed;
    try {
      parsed = mdxCodec.parse(source, { path: abs });
    } catch (err) {
      r.problems.push({
        level: "error",
        file: rel,
        message: `parse failed: ${err instanceof Error ? err.message : String(err)}`,
      });
      continue;
    }
    const problems: Problem[] = [];
    const changed = edit(parsed.tree, file, problems);
    r.problems.push(...problems.map((p) => ({ ...p, file: p.file ?? rel })));
    if (!changed) continue;
    const out = mdxCodec.stringify(parsed.tree, parsed.frontmatter);
    if (out === source) continue;
    r.synced.push(rel);
    if (!check) writeFileSync(abs, out);
  }
}

// ---------------------------------------------------------------------------
// mdast / MDX JSX helpers
// ---------------------------------------------------------------------------

export interface JsxAttr {
  type: "mdxJsxAttribute";
  name: string;
  value?: unknown;
}

export const isJsx = (n: AstNode) =>
  n.type === "mdxJsxTextElement" || n.type === "mdxJsxFlowElement";

export function attrs(n: AstNode): JsxAttr[] {
  return (n.attributes as JsxAttr[] | undefined) ?? [];
}

/** A literal string attribute, or undefined (absent or an expression). */
export function getAttr(n: AstNode, name: string): string | undefined {
  const a = attrs(n).find(
    (x) => x.type === "mdxJsxAttribute" && x.name === name,
  );
  if (!a) return undefined;
  if (typeof a.value === "string") return a.value;
  if (a.value === null || a.value === undefined) return "";
  return undefined;
}

export function hasClass(n: AstNode, cls: string) {
  return (getAttr(n, "className") ?? "").split(/\s+/).includes(cls);
}

export function attrList(pairs: [string, string][]): JsxAttr[] {
  return pairs.map(([name, value]) => ({
    type: "mdxJsxAttribute",
    name,
    value,
  }));
}

const attrKey = (list: JsxAttr[]) =>
  JSON.stringify(list.map((a) => [a.type, a.name, a.value ?? null]));

/** Replace attributes only when they differ (keeps the original bytes). */
export function setAttrs(n: AstNode, pairs: [string, string][]): boolean {
  const want = attrList(pairs);
  if (attrKey(attrs(n)) === attrKey(want)) return false;
  n.attributes = want;
  return true;
}

/** Replace children only when they differ structurally. */
export function setChildren(n: AstNode, kids: AstNode[]): boolean {
  const before = treeFingerprint({ type: "root", children: n.children ?? [] });
  const after = treeFingerprint({ type: "root", children: kids });
  if (before === after) return false;
  n.children = kids;
  return true;
}

export const text = (value: string): AstNode => ({ type: "text", value });
export const link = (url: string, kids: AstNode[]): AstNode => ({
  type: "link",
  url,
  title: null,
  children: kids,
});
export const jsxText = (
  name: string,
  pairs: [string, string][],
  kids: AstNode[],
): AstNode => ({
  type: "mdxJsxTextElement",
  name,
  attributes: attrList(pairs),
  children: kids,
});

/**
 * Depth-first walk with parent access. `fn` may return "skip" to not
 * descend into a node.
 */
export function walkTree(
  node: AstNode,
  fn: (n: AstNode, parent: AstNode | null, index: number) => void | "skip",
  parent: AstNode | null = null,
  index = 0,
) {
  if (fn(node, parent, index) === "skip") return;
  const kids = node.children ?? [];
  for (let i = 0; i < kids.length; i++) walkTree(kids[i]!, fn, node, i);
}

/**
 * Point snippet imports of one kind (`concepts`, `paths`) at the page's own
 * language when that language's snippet exists, else at English. Locale
 * pages arrive from Lingo with `/snippets/<kind>/en/…`; after a locale's
 * source JSON lands, `--sync` switches them over.
 */
export function syncSnippetImports(
  tree: AstNode,
  kind: string,
  lang: string,
  docsRoot: string,
): boolean {
  let changed = false;
  const re = new RegExp(
    `(["'])/snippets/${kind}/([a-z]{2}(?:-[A-Za-z]+)?)/([^"']+)\\1`,
    "g",
  );
  for (const node of tree.children ?? []) {
    if (node.type !== "mdxjsEsm" || typeof node.value !== "string") continue;
    const next = node.value.replace(
      re,
      (whole, q: string, from: string, rest: string) => {
        const target =
          lang !== DEFAULT_LOCALE &&
          existsSync(path.join(docsRoot, "snippets", kind, lang, rest))
            ? lang
            : DEFAULT_LOCALE;
        return target === from
          ? whole
          : `${q}/snippets/${kind}/${target}/${rest}${q}`;
      },
    );
    if (next !== node.value) {
      // Keep the estree in `data` from contradicting the new value: the
      // codec prints `value`, and nothing downstream reads the estree.
      node.value = next;
      delete node.data;
      changed = true;
    }
  }
  return changed;
}

// ---------------------------------------------------------------------------
// CLI helpers
// ---------------------------------------------------------------------------

export function parseFlags(argv: string[]) {
  const flags = new Set(
    argv.filter((a) => a.startsWith("--")).map((a) => a.slice(2)),
  );
  return {
    check: flags.has("check"),
    sync: flags.has("sync"),
    report: flags.has("report"),
  };
}

export function printResult(name: string, r: GeneratorResult, check: boolean) {
  const verb = check ? "would " : "";
  console.log(
    `${name}: ${verb}write ${r.written.length}, ${verb}remove ${r.removed.length}, ${verb}sync ${r.synced.length} page(s); ${r.problems.length} problem(s)`,
  );
  for (const f of r.written)
    console.log(`  ${check ? "stale" : "wrote"}: ${f}`);
  for (const f of r.removed)
    console.log(`  ${check ? "orphan" : "removed"}: ${f}`);
  for (const f of r.synced)
    console.log(`  ${check ? "unsynced" : "synced"}: ${f}`);
  for (const p of r.problems)
    console.log(
      `  ${p.level} ${p.file ?? ""}${p.file ? ": " : ""}${p.message}`,
    );
}

/** True when the module is the process entry point (`tsx src/generators/x.ts`). */
export function isMain(metaUrl: string) {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return path.resolve(entry) === path.resolve(new URL(metaUrl).pathname);
  } catch {
    return false;
  }
}
